```python
lst = [25, 32, 56, 70, 81, 47, 23, 92, 61, 5]
count = 0
def count_greater_than_50(lst):
    if len(lst) == 0:
        return 0
    elif len(lst) == 1:
        return 1 if lst[0] > 50 else 0
    else:
        return count_greater_than_50(lst[:len(lst)//2]) + count_greater_than_50(lst[len(lst)//2:]) 
count = count_greater_than_50(lst)
