<!DOCTYPE html>
<html>
<head>
  <title>Reinforcement Learning</title>
  <script src="https://cdn.jsdelivr.net/npm/@tensorflow/tfjs@3.9.0/dist/tf.min.js"></script>
  <script src="https://unpkg.com/@openai/gym-browser@0.4.0/dist/gym-browser.js"></script>
</head>
<body>
  <h1>Reinforcement Learning</h1>
  <canvas id="canvas"></canvas>
  <script>
    const env = new gym.make('CartPole-v0');
    const model = tf.sequential({
      layers: [
        tf.layers.dense({units: 32, activation: 'relu', inputShape: [4]}),
        tf.layers.dense({units: 2, activation: 'softmax'}),
      ]
    });
    model.compile({loss: 'categorical_crossentropy', optimizer: 'adam'});
    async function train() {
      const episodes = 100;
      const steps = 100;
      for (let i = 0; i < episodes; i++) {
        let state = env.reset();
        for (let j = 0; j < steps; j++) {
          const action = model.predict(tf.tensor(state).reshape([1, 4])).argMax(1).arraySync()[0];
          const [nextState, reward, done, info] = env.step(action);
          const target = model.predict(tf.tensor(state).reshape([1, 4]));
          if (done) {
            target[0][action] = reward;
          } else {
            const nextTarget = model.predict(tf.tensor(nextState).reshape([1, 4])).max().arraySync();
            target[0][action] = reward + 0.99 * nextTarget;
          }
          await model.fit(tf.tensor(state).reshape([1, 4]), target, {epochs: 1});
          state = nextState;
          if (done) break;
        }
      }
    }
    async function run() {
      let state = env.reset();
      while (true) {
        const action = model.predict(tf.tensor(state).reshape([1, 4])).argMax(1).arraySync()[0];
        const [nextState, reward, done, info] = env.step(action);
        env.render();
        state = nextState;
        if (done) break;
        await tf.nextFrame();
      }
    }
    train().then(run);
  </script>
</body>
</html>
