Here's an example code snippet in Swift that uses the Sieve of Eratosthenes algorithm to generate a sequence of five random prime numbers between 1000 and 10,000:
```swift
import Foundation
func sieveOfEratosthenes(_ n: Int) -> [Int] {
    var primes = Array(repeating: true, count: n + 1)
    primes[0] = false
    primes[1] = false

    for i in 2...Int(sqrt(Double(n))) {
        if primes[i] {
            var j = i * i
            while j <= n {
                primes[j] = false
                j += i
            }
        }
    }

    return primes.enumerated().compactMap { $0.element ? $0.offset : nil }
}
func generateRandomPrimes() -> [Int] {
    let primes = sieveOfEratosthenes(10000)
    var result = [Int]()

    while result.count < 5 {
        let randomIndex = Int.random(in: 0..<primes.count)
        let randomPrime = primes[randomIndex]
        if randomPrime >= 1000 && randomPrime <= 10000 {
            result.append(randomPrime)
        }
    }

    return result
}
let randomPrimes = generateRandomPrimes()
print(randomPrimes)
```
