```MATLAB
function cipher = vigenere_squared_encrypt(plaintext, key)
% Encrypt plaintext using Vigenere Squared algorithm with given key.
key_len = length(key);
cipher = '';
for i = 1:length(plaintext)
    x = uint8(plaintext(i));
    y = uint8(key(mod(i-1,key_len)+1));
    z = mod(x + y, 256);
