To create a horizontal bar chart in Go using the given data, you can use the "gonum.org/v1/plot" package. Here is an example code that can help you create a horizontal bar chart:
```
package main
import (
	"fmt"
	"math/rand"
	"gonum.org/v1/plot"
	"gonum.org/v1/plot/plotter"
	"gonum.org/v1/plot/plotutil"
	"gonum.org/v1/plot/vg"
)
func main() {
	ozarkRating := 8.4
	breakingBadRating := 9.5
	narcosRating := 8.8
	peakyBlindersRating := 8.8
	sopranosRating := 9.2
	ratings := []float64{ozarkRating, breakingBadRating, narcosRating, peakyBlindersRating, sopranosRating}
	labels := []string{"Ozark", "Breaking Bad", "Narcos", "Peaky Blinders", "The Sopranos"}
	// Create a new plot.
	p, err := plot.New()
	if err != nil {
		panic(err)
	}
	// Create a new horizontal bar chart.
	barChart, err := plotter.NewBarChart(plotter.Values(ratings))
	if err != nil {
		panic(err)
	}
	// Add labels to the horizontal bar chart.
	barChart.Labels = labels
	// Add the horizontal bar chart to the plot.
	p.Add(barChart)
	// Set the title and labels for the plot.
	p.Title.Text = "IMDb Ratings Comparison"
	p.Y.Label.Text = "TV Shows"
	p.X.Label.Text = "Ratings"
	// Save the plot to a PNG file.
	if err := p.Save(4*vg.Inch, 4*vg.Inch, "ratings.png"); err != nil {
		panic(err)
	}
	// Print a message to indicate that the plot has been saved.
	fmt.Println("The ratings comparison has been saved to ratings.png.")
}
```
This code will create a new plot, add a horizontal bar chart to it, set the title and labels, and save it to a PNG file named "ratings.png". You can customize the plot and the bar chart by modifying the code according to your needs.

