Sure, here's a C++ code that counts the number of occurrences of a specific string "target" in a longer string "str":
```c++
#include <iostream>
#include <string>
using namespace std;
int countOccurrences(string str, string target) {
    int count = 0;
    int n = str.length();
    int m = target.length();
    for (int i = 0; i <= n - m; i++) {
        bool found = true;
        for (int j = 0; j < m; j++) {
            if (str[i+j] != target[j]) {
                found = false;
                break;
            }
        }
        if (found) {
            count++;
        }
    }
    return count;
}
int main() {
    string str = "the quick brown fox jumps over the lazy dog";
    string target = "the";
    int count = countOccurrences(str, target);
    cout << "The string \"" << target << "\" occurs " << count << " times in the string \"" << str << "\"" << endl;
    return 0;
}
```
This code uses two nested loops to iterate over all possible substrings of length m in the longer string str. It then checks if each substring matches the target string using another loop. If it does, it increments the count variable. The time complexity of this algorithm is O(n*m), but since we assume that the length of the target string is small compared to the length of the longer string, we can consider it O(n).

