def sum_of_odd_integers():
    total = 0
    for i in range(102, 987, 2):
        if i % 10 == 0 or i % 10 == 2:
            continue
        digits = [int(d) for d in str(i)]
        if len(set(digits)) != len(digits):
            continue
        if digits != sorted(digits):
            continue
        total += i
    return total
